"""Integrity of the reference data generated by MATLAB."""

import hashlib
import json

from _refdata import REFDATA

MAX_TOTAL_BYTES = 8 * 1024 * 1024


def test_manifest_matches_files():
    manifest = json.loads((REFDATA / "manifest.json").read_text())
    assert manifest["matlab"]
    listed = {c["file"]: c["sha256"] for c in manifest["cases"]}
    on_disk = {p.relative_to(REFDATA).as_posix() for p in REFDATA.rglob("*.mat")}
    assert set(listed) == on_disk
    for file, sha in listed.items():
        assert hashlib.sha256((REFDATA / file).read_bytes()).hexdigest() == sha, file


def test_total_size():
    total = sum(p.stat().st_size for p in REFDATA.rglob("*.mat"))
    assert total <= MAX_TOTAL_BYTES, f"{total} bytes"
